use vstd::prelude::*;

verus! {

// Helper function to verify a character is a valid hex letter (A-F)
spec fn is_valid_hex_letter(c: char) -> bool {
    c == 'A' || c == 'B' || c == 'C' || c == 'D' || c == 'E' || c == 'F'
}

// Specification function to describe valid input format
spec fn is_valid_input(input: Seq<char>) -> bool {
    // Length is either 3 or 4
    (input.len() == 3 || input.len() == 4)
    // Second character is a space
    && input[1] == ' '
    // First and third characters are valid hex letters
    && is_valid_hex_letter(input[0])
    && is_valid_hex_letter(input[2])
    // If length is 4, fourth character is newline
    && (input.len() == 4 ==> input[3] == '\n')
}

// Specification function to describe the correct output
spec fn correct_output(input: Seq<char>, output: Seq<char>) -> bool {
    output.len() == 2
    && output[1] == '\n'
    && if input[0] < input[2] {
        output[0] == '<'
    } else if input[0] > input[2] {
        output[0] == '>'
    } else {
        output[0] == '='
    }
}

fn solve(stdin_input: Vec<char>) -> (result: Vec<char>)
    requires
        is_valid_input(stdin_input@),
    ensures
        correct_output(stdin_input@, result@),
{
    // Extract the first and second hex letters
    let first_letter = stdin_input[0];
    let second_letter = stdin_input[2];
    
    // Create the output vector
    let mut output: Vec<char> = Vec::new();
    
    // Compare and determine the result symbol
    let symbol: char = if first_letter < second_letter {
        '<'
    } else if first_letter > second_letter {
        '>'
    } else {
        '='
    };
    
    // Build the result
    output.push(symbol);
    output.push('\n');
    
    // Verify the output satisfies our postcondition
    assert(output@.len() == 2);
    assert(output@[0] == symbol);
    assert(output@[1] == '\n');
    assert(correct_output(stdin_input@, output@));
    
    output
}

} // verus!

